import type { Locale } from '$lib/stores/i18n.svelte';
// Guaraní: the long texts are served in Spanish (decided 2-nov-2026: nobody can
// check a Guaraní translation, and the stale ones said false things about the map).
// Readers fall back with `[locale] ?? .es`.
type LongText = Record<'es' | 'en' | 'pt', string> & Partial<Record<Locale, string>>;

export interface LocalizedMethodologyContent {
	howToRead: LongText;
	implications: LongText;
	method: { es: string; en: string };
}

export const METHOD_TYPES = {
	es: 'Tipos (clusters): las variables estandarizadas se procesan con PCA para validar independencia (se descartan variables con |r| > 0.70). Luego k-means agrupa hexágonos con perfiles multivariados similares. Cada hexágono se asigna al tipo cuyo centroide es más cercano. La calidad se valida con coeficiente de silueta. Los tipos no son un ranking — son perfiles cualitativos distintos.',
	en: 'Types (clusters): standardised variables are processed with PCA to validate independence (variables with |r| > 0.70 are discarded). K-means then groups hexagons with similar multivariate profiles. Each hexagon is assigned to the type whose centroid is nearest. Quality is validated using the silhouette coefficient. Types are not a ranking — they are qualitatively distinct profiles.',
};

